using Microsoft.EntityFrameworkCore;
using PA.Tickets.Application.Foundations;
using PA.Tickets.Application.Reporting;
using PA.Tickets.Infrastructure.Execution;
using PA.Tickets.Infrastructure.Persistence;
namespace PA.Tickets.Infrastructure.Reporting;
public sealed class AuditorReportingService(TicketsDbContext db,ExecutionDbContext execution,IAuthorizationService authorization,TimeProvider clock):IAuditorReportingService
{
 public async Task<AuditIntegrityResult> VerifyTicketAuditAsync(long ticketId,long actor,CancellationToken ct)
 {
  if(ticketId<=0)throw new ArgumentOutOfRangeException(nameof(ticketId));
  await authorization.EnsurePermissionAsync(actor,"AUDITOR_VIEW",null,ct);
  var authorizedTicketIds=await AuthorizedTicketIds(actor,ticketId,ct);
  if(!authorizedTicketIds.Contains(ticketId))throw new KeyNotFoundException("Ticket was not found.");
  var entityId=ticketId.ToString(System.Globalization.CultureInfo.InvariantCulture);
  var records=await db.Audits.AsNoTracking().Where(x=>x.EntityType=="TICKET"&&x.EntityId==entityId).OrderBy(x=>x.Id).ToArrayAsync(ct);
  var result=AuditChainVerifier.Verify(records,"TICKET",entityId);
  return new(ticketId,result.IsValid,result.RecordsVerified,result.FailedAuditId,result.Failure,clock.GetUtcNow());
 }

 public async Task<AuditStreamIntegrityResult> VerifyOperationalMetadataAuditAsync(string entityType,string entityId,long actor,CancellationToken ct)
 {
  await authorization.EnsurePermissionAsync(actor,"AUDITOR_VIEW",null,ct);
  if(!AuditChainVerifier.SupportsFormat(entityType)||entityType=="TICKET")
   throw new KeyNotFoundException("The requested audit stream was not found.");
  if(string.IsNullOrWhiteSpace(entityId)||entityId.Length>200)
   throw new KeyNotFoundException("The requested audit stream was not found.");
  var records=await db.Audits.AsNoTracking().Where(x=>x.EntityType==entityType&&x.EntityId==entityId).OrderBy(x=>x.Id).ToArrayAsync(ct);
  var result=AuditChainVerifier.Verify(records,entityType,entityId);
  return new(entityType,entityId,result.IsValid,result.RecordsVerified,result.FailedAuditId,result.Failure,clock.GetUtcNow());
 }

 static readonly TimeZoneInfo Zone=TimeZoneInfo.FindSystemTimeZoneById("Asia/Kolkata");
 static readonly IReadOnlyCollection<AuditorReportDefinition> Defs=new[]{
  D("AUDIT_ACTIVITY","Audit Activity","Chronological persisted ticket audit activity."),D("TICKET_AUDIT_TRAIL","Ticket Audit Trail","Persisted ticket lifecycle and audit events."),D("WORKFLOW_AUDIT","Workflow Audit","Persisted workflow step history."),D("APPROVAL_AUDIT","Approval Audit","Persisted approval history."),D("ASSIGNMENT_AUDIT","Assignment Audit","Persisted assignment history."),D("EVIDENCE_AUDIT","Evidence Audit","Persisted evidence and attachment metadata."),D("COMMUNICATION_AUDIT","Communication Audit","Persisted communication delivery metadata.")};
 static AuditorReportDefinition D(string c,string n,string d)=>new(c,n,d,new[]{"from","to","ticketId","actorId","entityType","action","correlationId","sort","page","pageSize"},new[]{"id","timestamp","ticketId","actorId","action","entityType","entityId","correlationId","reason"},"AUDITOR_VIEW");
 public IReadOnlyCollection<AuditorReportDefinition> Catalogue()=>Defs;
 public AuditorReportDefinition GetDefinition(string code)=>Defs.FirstOrDefault(x=>x.Code.Equals(code,StringComparison.OrdinalIgnoreCase))??throw new KeyNotFoundException("The requested auditor report was not found.");
 public async Task<AuditorReportResult> QueryAsync(string code,AuditorQueryRequest request,long actor,string? correlationId,CancellationToken ct){var d=GetDefinition(code);Validate(request);await authorization.EnsurePermissionAsync(actor,d.Permission,null,ct);var ids=await AuthorizedTicketIds(actor,request.TicketId,ct);var rows=code.ToUpperInvariant() switch{"AUDIT_ACTIVITY"=>await AuditActivity(request,ids,ct),"TICKET_AUDIT_TRAIL"=>await TicketTrail(request,ids,ct),"WORKFLOW_AUDIT"=>await Workflow(request,ids,ct),"APPROVAL_AUDIT"=>await Approval(request,ids,ct),"ASSIGNMENT_AUDIT"=>await Assignment(request,ids,ct),"EVIDENCE_AUDIT"=>await Evidence(request,ids,ct),"COMMUNICATION_AUDIT"=>await Communication(request,ids,ct),_=>throw new KeyNotFoundException("The requested auditor report was not found.")};return new AuditorReportResult(d.Code,d.Name,clock.GetUtcNow(),request,request.Page,request.PageSize,rows.Total,rows.Rows);}
 async Task<(int Total,IReadOnlyCollection<AuditorRow> Rows)> AuditActivity(AuditorQueryRequest r,IReadOnlyCollection<long> ids,CancellationToken ct){var q=db.Audits.AsNoTracking().Where(x=>x.EntityType=="TICKET"&&ids.Select(i=>i.ToString()).Contains(x.EntityId));q=AuditFilter(q,r);var total=await q.CountAsync(ct);var rows=await Order(q,r).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new AuditorRow(x.Id,x.At,long.Parse(x.EntityId),x.ActorId,x.Action,x.EntityType,x.EntityId,x.Reason,x.OldValue,x.NewValue,x.Reason,x.Hash,x.PreviousHash,null)).ToListAsync(ct);return(total,rows);}
 async Task<(int Total,IReadOnlyCollection<AuditorRow> Rows)> TicketTrail(AuditorQueryRequest r,IReadOnlyCollection<long> ids,CancellationToken ct){var q=db.Events.AsNoTracking().Where(x=>ids.Contains(x.TicketId));if(r.From is not null)q=q.Where(x=>x.At>=At(r.From.Value));if(r.To is not null)q=q.Where(x=>x.At<At(r.To.Value));if(r.ActorId is long a)q=q.Where(x=>x.ActorId==a);if(!string.IsNullOrWhiteSpace(r.Action))q=q.Where(x=>x.Type==r.Action);var total=await q.CountAsync(ct);var rows=await (r.Descending?q.OrderByDescending(x=>x.At).ThenByDescending(x=>x.Id):q.OrderBy(x=>x.At).ThenBy(x=>x.Id)).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new AuditorRow(x.Id,x.At,x.TicketId,x.ActorId,x.Type,x.Category,x.TicketId.ToString(),x.Reason,x.OldValue,x.NewValue,x.Reason,null,null,new{x.WorkItemId})).ToListAsync(ct);return(total,rows);}
 async Task<(int Total,IReadOnlyCollection<AuditorRow> Rows)> Workflow(AuditorQueryRequest r,IReadOnlyCollection<long> ids,CancellationToken ct){var q=from h in execution.WorkflowStepHistory.AsNoTracking() join s in execution.WorkflowSteps.AsNoTracking() on h.StepInstanceId equals s.Id join i in execution.WorkflowInstances.AsNoTracking() on s.WorkflowInstanceId equals i.Id where ids.Contains(i.TicketId) select new{h,i,s};if(r.From is not null)q=q.Where(x=>x.h.EventAt>=At(r.From.Value));if(r.To is not null)q=q.Where(x=>x.h.EventAt<At(r.To.Value));var total=await q.CountAsync(ct);var rows=await (r.Descending?q.OrderByDescending(x=>x.h.EventAt).ThenByDescending(x=>x.h.Id):q.OrderBy(x=>x.h.EventAt).ThenBy(x=>x.h.Id)).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new AuditorRow(x.h.Id,x.h.EventAt,x.i.TicketId,x.h.ActorId,x.h.Action,"WORKFLOW_STEP",x.s.Id.ToString(),x.h.CorrelationId,x.h.OldStatus,x.h.NewStatus,null,null,null,new{x.s.WorkItemId,x.s.ApprovalId})).ToListAsync(ct);return(total,rows);}
 async Task<(int Total,IReadOnlyCollection<AuditorRow> Rows)> Approval(AuditorQueryRequest r,IReadOnlyCollection<long> ids,CancellationToken ct){var q=from h in execution.ApprovalHistory.AsNoTracking() join a in execution.Approvals.AsNoTracking() on h.ApprovalId equals a.Id where ids.Contains(a.TicketId) select new{h,a};if(r.From is not null)q=q.Where(x=>x.h.CreatedAt>=At(r.From.Value));if(r.To is not null)q=q.Where(x=>x.h.CreatedAt<At(r.To.Value));var total=await q.CountAsync(ct);var rows=await (r.Descending?q.OrderByDescending(x=>x.h.CreatedAt).ThenByDescending(x=>x.h.Id):q.OrderBy(x=>x.h.CreatedAt).ThenBy(x=>x.h.Id)).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new AuditorRow(x.h.Id,x.h.CreatedAt,x.a.TicketId,x.h.ActorId,x.h.Action,"APPROVAL",x.a.Id.ToString(),x.h.CorrelationId,null,x.h.Decision,x.h.Comment,null,null,new{x.a.Level,x.a.ApproverId})).ToListAsync(ct);return(total,rows);}
 async Task<(int Total,IReadOnlyCollection<AuditorRow> Rows)> Assignment(AuditorQueryRequest r,IReadOnlyCollection<long> ids,CancellationToken ct){var q=db.Assignments.AsNoTracking().Where(x=>ids.Contains(x.TicketId));if(r.From is not null)q=q.Where(x=>x.AssignedAt>=At(r.From.Value));if(r.To is not null)q=q.Where(x=>x.AssignedAt<At(r.To.Value));var total=await q.CountAsync(ct);var rows=await (r.Descending?q.OrderByDescending(x=>x.AssignedAt).ThenByDescending(x=>x.Id):q.OrderBy(x=>x.AssignedAt).ThenBy(x=>x.Id)).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new AuditorRow(x.Id,x.AssignedAt,x.TicketId,x.AssignedBy,"ASSIGNED","ASSIGNMENT",x.Id.ToString(),null,null,x.AssignedTo==null?null:x.AssignedTo.Value.ToString(),x.Reason,null,null,new{x.WorkItemId,x.Type})).ToListAsync(ct);return(total,rows);}
 async Task<(int Total,IReadOnlyCollection<AuditorRow> Rows)> Evidence(AuditorQueryRequest r,IReadOnlyCollection<long> ids,CancellationToken ct){var q=from e in db.Evidence.AsNoTracking() join a in db.Attachments.AsNoTracking() on e.AttachmentId equals a.Id into ag from a in ag.DefaultIfEmpty() where ids.Contains(e.TicketId) select new{e,a};if(r.From is not null)q=q.Where(x=>x.e.CreatedAt>=At(r.From.Value));if(r.To is not null)q=q.Where(x=>x.e.CreatedAt<At(r.To.Value));var total=await q.CountAsync(ct);var rows=await q.OrderByDescending(x=>x.e.CreatedAt).ThenByDescending(x=>x.e.Id).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new AuditorRow(x.e.Id,x.e.CreatedAt,x.e.TicketId,x.e.CreatedBy,"EVIDENCE_CREATED","EVIDENCE",x.e.Id.ToString(),null,null,x.e.Status,x.e.Description,null,null,new{x.e.AttachmentId,FileName=x.a==null?null:x.a.FileName,ContentType=x.a==null?null:x.a.ContentType,Size=x.a==null?null:x.a.FileSize,Sha256=x.a==null?null:x.a.Sha256Hash})).ToListAsync(ct);return(total,rows);}
 async Task<(int Total,IReadOnlyCollection<AuditorRow> Rows)> Communication(AuditorQueryRequest r,IReadOnlyCollection<long> ids,CancellationToken ct){var q=db.Communications.AsNoTracking().Where(x=>ids.Contains(x.TicketId));if(r.From is not null)q=q.Where(x=>x.CommunicationAt>=At(r.From.Value));if(r.To is not null)q=q.Where(x=>x.CommunicationAt<At(r.To.Value));var total=await q.CountAsync(ct);var rows=await q.OrderByDescending(x=>x.CommunicationAt).ThenByDescending(x=>x.Id).Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new AuditorRow(x.Id,x.CommunicationAt,x.TicketId,x.RecordedBy,"COMMUNICATION", "COMMUNICATION",x.PublicId,x.CorrelationId,null,x.Status,null,null,null,new{x.Channel,x.ProviderCode,x.TemplateCode,x.RetryCount,x.SentAt,x.DeliveredAt,x.FailedAt,x.FailureCode,x.FailureClassification})).ToListAsync(ct);return(total,rows);}
 async Task<IReadOnlyCollection<long>> AuthorizedTicketIds(long actor,long? ticketId,CancellationToken ct){var now=clock.GetUtcNow();var u=await db.AdministrationUsers.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==actor&&x.Active,ct)??throw new UnauthorizedAccessException();var admin=await(from m in db.AdministrationUserRoles.AsNoTracking() join r in db.AdministrationRoles.AsNoTracking() on m.RoleId equals r.Id where m.UserId==actor&&m.Active&&m.ValidFrom<=now&&(m.ValidTo==null||m.ValidTo>now)&&r.Active&&r.Code=="ADMINISTRATOR" select r.Id).AnyAsync(ct);var clients=db.AdministrationUserClients.AsNoTracking().Where(x=>x.UserId==actor&&x.Active&&x.ValidFrom<=now&&(x.ValidTo==null||x.ValidTo>now)).Select(x=>x.ClientId);var q=admin?db.Tickets.AsNoTracking().Select(x=>x.Id):db.Tickets.AsNoTracking().Where(x=>(x.CurrentAssignee==actor&&(!x.CurrentDepartmentId.HasValue||x.CurrentDepartmentId==u.DepartmentId)&&(!x.CurrentTeamId.HasValue||x.CurrentTeamId==u.TeamId)&&(!x.ClientId.HasValue||clients.Contains(x.ClientId.Value)))||(u.DepartmentId.HasValue&&x.CurrentDepartmentId==u.DepartmentId)||(u.TeamId.HasValue&&x.CurrentTeamId==u.TeamId)||(x.ClientId.HasValue&&clients.Contains(x.ClientId.Value))).Select(x=>x.Id);if(ticketId.HasValue)q=q.Where(x=>x==ticketId);return await q.ToListAsync(ct);}
 static IQueryable<AuditRow> AuditFilter(IQueryable<AuditRow> q,AuditorQueryRequest r){if(r.From is not null)q=q.Where(x=>x.At>=At(r.From.Value));if(r.To is not null)q=q.Where(x=>x.At<At(r.To.Value));if(r.ActorId is long a)q=q.Where(x=>x.ActorId==a);if(!string.IsNullOrWhiteSpace(r.Action))q=q.Where(x=>x.Action==r.Action);if(!string.IsNullOrWhiteSpace(r.EntityType))q=q.Where(x=>x.EntityType==r.EntityType);if(!string.IsNullOrWhiteSpace(r.CorrelationId))q=q.Where(x=>x.Reason==r.CorrelationId);return q;}
 static IOrderedQueryable<AuditRow> Order(IQueryable<AuditRow> q,AuditorQueryRequest r)=>r.Descending?q.OrderByDescending(x=>x.At).ThenByDescending(x=>x.Id):q.OrderBy(x=>x.At).ThenBy(x=>x.Id);
 static void Validate(AuditorQueryRequest r){if(r.Page<1||r.PageSize<1||r.PageSize>100)throw new ArgumentException("Invalid page or page size.");if(r.From.HasValue&&r.To.HasValue&&r.From>=r.To)throw new ArgumentException("Invalid date range.");if(!string.Equals(r.Sort,"timestamp",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Unsupported sort.");}
 static DateTimeOffset At(DateOnly d)=>new(TimeZoneInfo.ConvertTimeToUtc(d.ToDateTime(TimeOnly.MinValue),Zone));
}
